SELECT 'JE_LINES' key,
'DESCRIPTION'||'~'||'JE_HEADER_ID'||'~'||'JE_LINE_NUM'||'~'||'LEDGER_ID'||'~'||'PERIOD_NAME'||'~'||'CURRENCY_CODE'||'~'||'STATUS'||'~'||'CREATION_DATE'||'~'||'CREATED_BY'||'~'||'LAST_UPDATE_DATE'||'~'||'CURRENCY_CONVERSION_RATE'||'~'||'LAST_UPDATED_BY'||'~'||'CURRENCY_CONVERSION_TYPE'||'~'||'CURRENCY_CONVERSION_DATE'||'~'||
'OBJECT_VERSION_NUMBER'||'~'||'CODE_COMBINATION_ID'||'~'||'EFFECTIVE_DATE'||'~'||'ENTERED_DR'||'~'||'ACCOUNTED_DR'||'~'||'ENTERED_CR'||'~'||'ACCOUNTED_CR'||'~'||
'INVOICE_DATE'||'~'||'ATTRIBUTE_CATEGORY'||'~'||'ATTRIBUTE_CATEGORY2'||'~'||'ATTRIBUTE_CATEGORY3'||'~'||'ATTRIBUTE_CATEGORY4'||'~'||'ATTRIBUTE1'||'~'||'ATTRIBUTE2'||'~'||'ATTRIBUTE3'||'~'||'ATTRIBUTE4'||'~'||
'ATTRIBUTE5'||'~'||'ATTRIBUTE6'||'~'||'ATTRIBUTE7'||'~'||'ATTRIBUTE8'||'~'||'ATTRIBUTE9'||'~'||'ATTRIBUTE10'||'~'||'ATTRIBUTE11'||'~'||'ATTRIBUTE12'||'~'||'ATTRIBUTE13'||'~'||'ATTRIBUTE14'||'~'||
'ATTRIBUTE15'||'~'||'ATTRIBUTE16'||'~'||'ATTRIBUTE17'||'~'||'ATTRIBUTE18'||'~'||'ATTRIBUTE19'||'~'||'ATTRIBUTE20'||'~'||'GLOBAL_ATTRIBUTE_DATE1'||'~'||'GLOBAL_ATTRIBUTE_DATE2'||'~'||
'GLOBAL_ATTRIBUTE_DATE3'||'~'||'GLOBAL_ATTRIBUTE_DATE4'||'~'||'GLOBAL_ATTRIBUTE_DATE5'||'~'||'GLOBAL_ATTRIBUTE_NUMBER1'||'~'||
'GLOBAL_ATTRIBUTE_NUMBER2'||'~'||'GLOBAL_ATTRIBUTE_NUMBER3'||'~'||'GLOBAL_ATTRIBUTE_NUMBER4'||'~'||'GLOBAL_ATTRIBUTE_NUMBER5'||'~'||'GLOBAL_ATTRIBUTE_CATEGORY'||'~'||
'GLOBAL_ATTRIBUTE1'||'~'||'GLOBAL_ATTRIBUTE2'||'~'||'GLOBAL_ATTRIBUTE3'||'~'||'GLOBAL_ATTRIBUTE4'||'~'||'GLOBAL_ATTRIBUTE5'||'~'||'GLOBAL_ATTRIBUTE6'||'~'||
'GLOBAL_ATTRIBUTE7'||'~'||'GLOBAL_ATTRIBUTE8'||'~'||'GLOBAL_ATTRIBUTE9'||'~'||'GLOBAL_ATTRIBUTE10'||'~'||'REFERENCE_1'||'~'||'REFERENCE_2'||'~'||'REFERENCE_3'||'~'||'REFERENCE_4'||'~'||
'REFERENCE_5'||'~'||'REFERENCE_6'||'~'||'REFERENCE_7'||'~'||'REFERENCE_8'||'~'||'REFERENCE_9'||'~'||'REFERENCE_10'||'~'||'GL_SL_LINK_ID'||'~'||'GL_SL_LINK_TABLE'||'~'||'TAX_CODE'||'~'||'INVOICE_IDENTIFIER'||'~'||'INVOICE_AMOUNT'||'~'||'STAT_AMOUNT'||'~'||'IGNORE_RATE_FLAG'||'~'||'USSGL_TRANSACTION_CODE'||'~'||'SUBLEDGER_DOC_SEQUENCE_ID'||'~'||'SUBLEDGER_DOC_SEQUENCE_VALUE'||'~'||
'TAXABLE_LINE_FLAG'||'~'||'TAX_TYPE_CODE'||'~'||'TAX_CODE_ID'||'~'||'TAX_ROUNDING_RULE_CODE'||'~'||'AMOUNT_INCLUDES_TAX_FLAG'||'~'||'TAX_DOCUMENT_IDENTIFIER'||'~'||'TAX_DOCUMENT_DATE'||'~'||'TAX_CUSTOMER_NAME'||'~'||'TAX_CUSTOMER_REFERENCE'||'~'||'TAX_REGISTRATION_NUMBER' JE_LINES
FROM DUAL	
UNION ALL
SELECT 'JE_LINES' key,
 REPLACE(REPLACE(REPLACE(DESCRIPTION,CHR(10),''),CHR(13),''),'~',' ' )||'~'||JE_HEADER_ID||'~'||JE_LINE_NUM||'~'||LEDGER_ID||'~'||PERIOD_NAME||'~'||CURRENCY_CODE||'~'||STATUS||'~'||CREATION_DATE||'~'||CREATED_BY||'~'||LAST_UPDATE_DATE||'~'||CURRENCY_CONVERSION_RATE||'~'||LAST_UPDATED_BY||'~'||CURRENCY_CONVERSION_TYPE||'~'||CURRENCY_CONVERSION_DATE||'~'||
OBJECT_VERSION_NUMBER||'~'||CODE_COMBINATION_ID||'~'||EFFECTIVE_DATE||'~'||ENTERED_DR||'~'||ACCOUNTED_DR||'~'||ENTERED_CR||'~'||ACCOUNTED_CR||'~'||
INVOICE_DATE||'~'|| ATTRIBUTE_CATEGORY||'~'||ATTRIBUTE_CATEGORY2||'~'||ATTRIBUTE_CATEGORY3||'~'|| ATTRIBUTE_CATEGORY4||'~'||ATTRIBUTE1||'~'||ATTRIBUTE2||'~'||ATTRIBUTE3||'~'||ATTRIBUTE4||'~'||
ATTRIBUTE5||'~'||ATTRIBUTE6||'~'||ATTRIBUTE7||'~'||ATTRIBUTE8||'~'||ATTRIBUTE9||'~'||ATTRIBUTE10||'~'||ATTRIBUTE11||'~'||ATTRIBUTE12||'~'||ATTRIBUTE13||'~'||ATTRIBUTE14||'~'||
ATTRIBUTE15||'~'||ATTRIBUTE16||'~'||ATTRIBUTE17||'~'||ATTRIBUTE18||'~'||ATTRIBUTE19||'~'||ATTRIBUTE20||'~'||GLOBAL_ATTRIBUTE_DATE1||'~'||GLOBAL_ATTRIBUTE_DATE2||'~'||
GLOBAL_ATTRIBUTE_DATE3||'~'||GLOBAL_ATTRIBUTE_DATE4||'~'||GLOBAL_ATTRIBUTE_DATE5||'~'||GLOBAL_ATTRIBUTE_NUMBER1||'~'||
GLOBAL_ATTRIBUTE_NUMBER2||'~'||GLOBAL_ATTRIBUTE_NUMBER3||'~'||GLOBAL_ATTRIBUTE_NUMBER4||'~'||GLOBAL_ATTRIBUTE_NUMBER5||'~'||GLOBAL_ATTRIBUTE_CATEGORY||'~'||
GLOBAL_ATTRIBUTE1||'~'||GLOBAL_ATTRIBUTE2||'~'||GLOBAL_ATTRIBUTE3||'~'||GLOBAL_ATTRIBUTE4||'~'||GLOBAL_ATTRIBUTE5||'~'||GLOBAL_ATTRIBUTE6||'~'||
GLOBAL_ATTRIBUTE7||'~'||GLOBAL_ATTRIBUTE8||'~'||GLOBAL_ATTRIBUTE9||'~'||GLOBAL_ATTRIBUTE10||'~'||REFERENCE_1||'~'||REFERENCE_2||'~'||REFERENCE_3||'~'||REFERENCE_4||'~'||
REFERENCE_5||'~'||REFERENCE_6||'~'||REFERENCE_7||'~'||REFERENCE_8||'~'||REFERENCE_9||'~'||REFERENCE_10||'~'||GL_SL_LINK_ID||'~'||GL_SL_LINK_TABLE||'~'||TAX_CODE||'~'||INVOICE_IDENTIFIER||'~'||INVOICE_AMOUNT||'~'||STAT_AMOUNT||'~'||IGNORE_RATE_FLAG||'~'||USSGL_TRANSACTION_CODE||'~'||SUBLEDGER_DOC_SEQUENCE_ID||'~'||SUBLEDGER_DOC_SEQUENCE_VALUE||'~'||
TAXABLE_LINE_FLAG||'~'||TAX_TYPE_CODE||'~'||TAX_CODE_ID||'~'||TAX_ROUNDING_RULE_CODE||'~'||AMOUNT_INCLUDES_TAX_FLAG||'~'||TAX_DOCUMENT_IDENTIFIER||'~'||TAX_DOCUMENT_DATE||'~'||TAX_CUSTOMER_NAME||'~'||TAX_CUSTOMER_REFERENCE||'~'||TAX_REGISTRATION_NUMBER
FROM GL_JE_LINES a
 where ((:P_FROM_DATE IS NOT NULL AND :P_TO_DATE IS NOT NULL AND a.last_update_date between :P_FROM_DATE AND :P_TO_DATE) or
			(:P_FROM_DATE IS NULL AND :P_TO_DATE IS NULL AND a.last_update_date > (SELECT MAX(ERH.processstart)
                                         FROM ess_request_history ERH
                                             ,ess_request_property ERP
                                        WHERE ERH.requestid = ERP.requestid
                                          AND ERH.definition = 'JobDefinition://oracle/apps/ess/custom/cclf/CCLF_DL_GL_Lines'
                                          AND ERH.executable_status = 'SUCCEEDED'
                                          AND ERP.name = 'submit.argument1'
                             	          AND ERP.value IS NULL)))